import{_ as i,C as t,o as l,c as d,j as o,a as h,E as s,a2 as r}from"./chunks/framework.sc8Z_ZE3.js";const k=JSON.parse('{"title":"Chat","description":"","frontmatter":{},"headers":[],"relativePath":"work/chat.md","filePath":"work/chat.md"}'),c={name:"work/chat.md"};function g(p,e,u,f,m,w){const n=t("Badge"),a=t("Shot");return l(),d("div",null,[e[0]||(e[0]=o("h1",{id:"chat",tabindex:"-1"},[h("Chat "),o("a",{class:"header-anchor",href:"#chat","aria-label":'Permalink to "Chat"'},"​")],-1)),s(n,{type:"built",text:"Built"}),e[1]||(e[1]=r(' Chat is where you talk to agents in a Workspace, see the tools they use and decide on approvals in the same conversation.<h2 id="workspaces" tabindex="-1">Workspaces <a class="header-anchor" href="#workspaces" aria-label="Permalink to &quot;Workspaces&quot;">​</a></h2><p>Every chat belongs to a Workspace. You pick it with the one <strong>Workspace</strong> switch at the top of the left rail; all areas share it. Administrators can also pick <strong>Global · no workspace</strong>. The sidebar groups chats by Workspace. Chats from Workspaces you cannot select right now move into a collapsed section <strong>Other workspaces (inactive or unavailable)</strong>. They are not deleted.</p><h2 id="threads" tabindex="-1">Threads <a class="header-anchor" href="#threads" aria-label="Permalink to &quot;Threads&quot;">​</a></h2><p>Start a thread with <strong>New chat</strong>. Each thread&#39;s menu has <strong>Pin</strong>, <strong>Rename</strong>, <strong>Select</strong>, <strong>Archive</strong>, <strong>Export evidence PDF</strong> and <strong>Export analysis JSON</strong>. Administrators also see <strong>Delete…</strong>.</p><ul><li><strong>Search.</strong> Type in <strong>Search all chats</strong>. Press <code>/</code> outside a text field to jump there and <code>Esc</code> to clear it. The search matches the title or your first message in the chat, across all your Workspaces.</li><li><strong>Bulk actions.</strong> <strong>Select</strong> turns on selection mode. Click rows (Shift-click for a range), then archive them together after a confirmation. Administrators can also delete them; deleting cannot be undone.</li><li><strong>Archive.</strong> Archived chats leave the list. <strong>Archived chats</strong> at the bottom of the sidebar lists them, and <strong>Restore</strong> brings one back.</li><li><strong>Re-run.</strong> On your own message, <strong>Edit</strong> changes it. Sending re-runs the thread from there and discards later turns. <strong>Draft</strong> copies it into the composer instead. On a reply, <strong>Retry</strong> re-runs the thread from that turn. The reply&#39;s <strong>⋯</strong> menu adds <strong>Retry the preceding prompt</strong>, <strong>Read aloud</strong> and, when recorded, <strong>Thinking details</strong>, <strong>Performance details</strong> and <strong>Open trace</strong>.</li><li><strong>Resume.</strong> After an approval decision the thread continues in place. A notice reads <strong>Resume after approval</strong> or <strong>Resume after rejection</strong>. A rejected action is not tried again, and the agent takes a safer path.</li></ul><h2 id="the-composer" tabindex="-1">The composer <a class="header-anchor" href="#the-composer" aria-label="Permalink to &quot;The composer&quot;">​</a></h2><ul><li><strong>Workflow.</strong> The default is <strong>Automatic</strong>: the platform may suggest a published workflow that fits. Then the reply shows <strong>Needs confirmation</strong> until you decide. You can also pick a workflow yourself.</li><li><strong>Model.</strong> Reads <strong>Automatic</strong> plus the model name. Open it to choose another model from the list.</li><li><strong>Thinking.</strong> Three answer modes: <strong>Off</strong> (answer directly), <strong>Quick</strong> (think briefly, the default) and <strong>Thorough</strong> (think longer).</li><li><strong>Advanced.</strong> Not an answer mode. It shows <strong>Run on</strong>: <strong>Server</strong> or one of your paired devices. Offline or paused devices are listed but cannot be picked.</li></ul><p>Type <code>@</code> and the start of a name to address a specific agent; otherwise the platform routes the request. Type <code>/</code> in an empty input for commands:</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/generate-task-from-chat</code></td><td>Generate a task definition from this conversation</td></tr><tr><td><code>/generate-workflow</code></td><td>Generate a draft workflow from this conversation</td></tr></tbody></table><h2 id="tool-steps" tabindex="-1">Tool steps <a class="header-anchor" href="#tool-steps" aria-label="Permalink to &quot;Tool steps&quot;">​</a></h2><p>Tool use folds into one line, such as &quot;Used 4 tools · 12 s&quot; (&quot;Using tools · 2 so far&quot; while running). Expand it for each step. A failed step always stays visible. A step the Workspace rules refused shows as &quot;… blocked by the workspace rules&quot; with the rule&#39;s reason. See <a href="/docs/rules/policies">Rules</a>.</p><h2 id="approvals-in-the-conversation" tabindex="-1">Approvals in the conversation <a class="header-anchor" href="#approvals-in-the-conversation" aria-label="Permalink to &quot;Approvals in the conversation&quot;">​</a></h2><p>An action that needs a person shows a card <strong>Human approval required</strong>. Where available it shows <strong>Before</strong>, <strong>Planned change</strong> and <strong>Inspect governed change</strong>.</p><ul><li>Tool approval: <strong>Deny</strong>, <strong>Allow once</strong> and, for Workspace admins and owners only, <strong>Always for this Workspace</strong>. That last button adds a standing rule for exactly the scope shown, for example one command. It is never offered for a write to another system, such as a connector, a REST call or a database.</li><li>Approval gate in a workflow run: <strong>Reject</strong> or <strong>Approve &amp; resume</strong>, with <strong>Who may decide: …</strong> naming the allowed roles.</li><li>A write to a connector: a card <strong>Confirm before Octryx writes</strong> lists every field the call writes, with <strong>Reject</strong> or <strong>Approve</strong>. It covers only this call; the next write asks again.</li><li>A plan of several writes: a card <strong>Confirm the write plan</strong> lists the writes and their scope, with <strong>Reject</strong> or <strong>Approve</strong>. After you approve, these writes run without asking again. Anything outside the scope asks again.</li></ul><p>Afterwards the card shows <strong>Approved</strong>, <strong>Denied</strong> or <strong>Timed out</strong>.</p><h2 id="sources-and-citations" tabindex="-1">Sources and citations <a class="header-anchor" href="#sources-and-citations" aria-label="Permalink to &quot;Sources and citations&quot;">​</a></h2>',17)),s(a,{src:"/shots/chat-sources.png",alt:"A chat in the Demo Shop: the assistant uses Knowledge Search and Knowledge Read, then answers with a citation on every point",caption:"An agent searches the Workspace knowledge, reads the right document and cites it on every point."}),e[2]||(e[2]=r('<p>Each answer has a <strong>Sources · n</strong> button (or <strong>Sources · none cited</strong>). It opens <strong>Sources &amp; evidence</strong>, which lists each cited link with the statement it supports. A marker such as <code>[1]</code> in the text opens the same panel on that source. Opening a source uses your own permissions. A citation shows where a statement comes from; it does not verify the claim.</p><h2 id="previews-of-html-and-office-files" tabindex="-1">Previews of HTML and Office files <a class="header-anchor" href="#previews-of-html-and-office-files" aria-label="Permalink to &quot;Previews of HTML and Office files&quot;">​</a></h2><p>Files an agent produces open in the <strong>Preview</strong> side panel, with <strong>Expand</strong>, <strong>Open</strong> and <strong>Download</strong>.</p><ul><li><strong>HTML</strong> renders in an isolated frame with no access to your session.</li><li><strong>Word, Excel and PowerPoint</strong> files open on a rendered <strong>Preview</strong>. Tabs switch to <strong>Text</strong>, <strong>Outline</strong>, <strong>Annotations</strong>, <strong>Stats</strong>, <strong>Issues</strong> and, for Word, <strong>Forms</strong>. <strong>Open PDF</strong> opens the rendered file, and <strong>Details</strong> shows file details beside it. If rendering fails you see <strong>Preview unavailable</strong>, and the other tabs still work.</li><li>Images, PDFs and text files preview directly.</li></ul><h2 id="verification-note-on-replies" tabindex="-1">Verification note on replies <a class="header-anchor" href="#verification-note-on-replies" aria-label="Permalink to &quot;Verification note on replies&quot;">​</a></h2><p>A status row under each reply says what was checked. A normal chat answer reads <strong>Finished, unverified</strong> with <strong>Verification: Not evaluated</strong>: no verification step ran. <strong>Evidence</strong> shows <strong>Sources cited</strong>, <strong>No source evidence this turn</strong>, <strong>Some claims unsourced</strong> or <strong>Answer withheld</strong>. <strong>Some claims unsourced</strong> means the answer is shown in full, and each claim without a source is marked in place. <strong>Answer withheld</strong> means the answer did not cite its sources and was not shown. <strong>Details</strong> opens the full execution record. Other states, such as <strong>Waiting for approval</strong> or <strong>Failed</strong>, add a <strong>Next:</strong> hint.</p><p>Treat an unverified answer as a first draft and check it before you rely on it.</p><h2 id="limits-today" tabindex="-1">Limits today <a class="header-anchor" href="#limits-today" aria-label="Permalink to &quot;Limits today&quot;">​</a></h2><ul><li>Search covers the title and your first message, not the whole conversation.</li><li>There are only two <code>/</code> commands.</li><li>Only Workspace admins and owners can use <strong>Always for this Workspace</strong>.</li><li>Only administrators can delete chats.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/rules/policies">Rules and policies</a></li><li><a href="/docs/work/mobile">Mobile web app</a></li></ul>',11))])}const y=i(c,[["render",g]]);export{k as __pageData,y as default};
